import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
import {publicationIdentity,reviewedPublicationVariation,publicationProductGroups} from './product-deduplication.mjs';
const rows=[{id:'b2ejp8pkiWYOgBAdeXto',titulo:'Celular Samsung Galaxy S26 5G, 256GB, 12GB RAM, Galaxy AI, Câmera Tripla de 50+12+10, Tela de 6.3" Preto',listing:'MLB6501275666'},{id:'B3HTtYZQAYonACif4tW1',titulo:'Tênis New Speed Esporte Masculino 100% Original Caminhada',listing:'MLB5157546240'}];
test('triagem64 protege identidade operação e idempotência sem outra variante',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'187320292345'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('S26 não recebe qualificação temporal ou recurso do Ultra',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,'Samsung Galaxy S26 5G 256 GB/12 GB — preto');assert.doesNotMatch(x.pros,/última geração|melhor|Snapdragon|privacidade|60W/i);assert.match(x.comentario,/Não transferimos funções do S26\+ ou do Ultra/);});
test('New Speed corrigido mantém exceção exata e variação distinta sem unir registros',()=>{const a={...rows[1],link:'https://produto.mercadolivre.com.br/MLB-5157546240-_JM?searchVariation=187320292345',linkAfiliado:'https://meli.la/1CVi5wv'},b={...a,id:'1RCE8RtBHkc6aVkKZ6xB',link:a.link.replace('187320292345','207161735289'),linkAfiliado:'https://meli.la/33X4bbf'},x=correctProductData(a);assert.equal(reviewedPublicationVariation(x)?.variationId,'187320292345');assert.equal(publicationProductGroups([x,correctProductData(b)]).length,2);for(const patch of [{id:'desconhecido'},{link:a.link.replace('187320292345','999')},{linkAfiliado:'https://meli.la/outro'},{titulo:x.titulo+' outro modelo'}])assert.equal(reviewedPublicationVariation({...x,...patch}),null);assert.equal(publicationIdentity(x).listingId,'MLB5157546240');});
test('lanterna somente troca título e mantém revisão de anúncio e seus limites',()=>{const p={id:'BcfEuX1oed02O8pYXKyg',titulo:'Lanterna de cabeça 12 modos 100000 Lumens',link:'https://www.mercadolivre.com.br/p/MLB63116023?wid=MLB6038239378',preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.titulo,'Lanterna de cabeça recarregável com 12 modos — especificações a confirmar');assert.match(x.comentario,/USB-C e carga rápida continuam sem confirmação/);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);});
